const raw = $input.first().json;

// Parser le body correctement — supporte string avec = parasite
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try {
      data = JSON.parse(rawBody);
    } catch(e) {
      data = raw;
    }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

if (!data.task_id) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      error_message: "task_id manquant",
      task_id: "unknown",
      language: data.language || "javascript",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!Array.isArray(data.files) || data.files.length === 0) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      error_message: "Champ files manquant ou tableau vide",
      task_id: data.task_id,
      language: data.language || "javascript",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    valid: true,
    task_id: String(data.task_id),
    language: String(data.language || "javascript"),
    files: data.files,
    files_count: data.files.length
  }
}];

const input = $input.first().json;

// Sécurité : limiter la taille analysée
const MAX_FILE_SIZE = 50000;
const files = (input.files || []).map(f => ({
  ...f,
  content: (f.content || '').substring(0, MAX_FILE_SIZE)
}));

let critical = [];
let warnings = [];

// ── Patterns de détection ──────────────────────────────────────────────────
const patterns = [
  // Clés cloud
  { name: "AWS Access Key",    regex: /AKIA[0-9A-Z]{16}/g,          severity: "critical", owasp: "A02:2021" },
  { name: "AWS Secret Key",    regex: /[A-Za-z0-9\/+=]{40}/g,       severity: "high",     owasp: "A02:2021" },
  { name: "GCP API Key",       regex: /AIza[0-9A-Za-z-_]{35}/g,     severity: "critical", owasp: "A02:2021" },
  { name: "Azure Key",         regex: /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, severity: "medium", owasp: "A02:2021" },

  // Tokens de services
  { name: "OpenAI Key",        regex: /sk-[a-zA-Z0-9]{32,}/g,       severity: "critical", owasp: "A02:2021" },
  { name: "GitHub Token",      regex: /ghp_[a-zA-Z0-9]{36}/g,       severity: "critical", owasp: "A02:2021" },
  { name: "GitHub OAuth",      regex: /gho_[a-zA-Z0-9]{36}/g,       severity: "critical", owasp: "A02:2021" },
  { name: "Stripe Key",        regex: /sk_live_[0-9a-zA-Z]{24}/g,   severity: "critical", owasp: "A02:2021" },
  { name: "Stripe Test Key",   regex: /sk_test_[0-9a-zA-Z]{24}/g,   severity: "high",     owasp: "A02:2021" },
  { name: "Slack Token",       regex: /xox[baprs]-[0-9a-zA-Z-]{10,}/g, severity: "high",  owasp: "A02:2021" },
  { name: "Twilio Key",        regex: /AC[a-zA-Z0-9]{32}/g,         severity: "high",     owasp: "A02:2021" },

  // Clés cryptographiques
  { name: "Private Key PEM",   regex: /-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----/g, severity: "critical", owasp: "A02:2021" },
  { name: "JWT Token",         regex: /eyJ[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+/g, severity: "high", owasp: "A02:2021" },

  // Secrets génériques
  { name: "Hardcoded Password", regex: /password\s*[:=]\s*['"][^'"]{6,}['"]/gi, severity: "high", owasp: "A02:2021" },
  { name: "Hardcoded Secret",   regex: /(secret|api_key|apikey|auth_token)\s*[:=]\s*['"][^'"]{8,}['"]/gi, severity: "high", owasp: "A02:2021" },

  // Groq/Anthropic keys (spécifique au projet)
  { name: "Groq API Key",      regex: /gsk_[a-zA-Z0-9]{50,}/g,     severity: "critical", owasp: "A02:2021" },
  { name: "Anthropic Key",     regex: /sk-ant-[a-zA-Z0-9-]{50,}/g, severity: "critical", owasp: "A02:2021" }
];

// ── Scan des fichiers ──────────────────────────────────────────────────────
for (const file of files) {
  const content = file.content || "";
  const path    = file.path    || "unknown";

  // Ignorer les fichiers de config exemple et .env.example
  if (path.includes('.env.example') || path.includes('.env.sample')) continue;

  for (const rule of patterns) {
    // Reset regex lastIndex
    rule.regex.lastIndex = 0;
    const matches = content.match(rule.regex);
    if (!matches) continue;

    // Dédupliquer par fichier+règle
    const unique = [...new Set(matches)];
    for (const m of unique) {
      // Masquer la valeur pour ne pas exposer le secret dans les logs
      const masked = m.substring(0, 6) + '****' + m.substring(m.length - 4);
      const issue = {
        rule:        rule.name,
        severity:    rule.severity === "critical" ? "high" : rule.severity,
        owasp:       rule.owasp,
        file:        path,
        description: `${rule.name} détecté dans ${path} : ${masked}`,
        impact:      "Exposition de credentials — accès non autorisé possible",
        fix:         `Déplacer dans process.env et ajouter ${path} au .gitignore`
      };

      if (rule.severity === "critical" || rule.severity === "high") {
        critical.push(issue);
      } else {
        warnings.push(issue);
      }
    }
  }
}

// -- Detection par entropie (approche gitleaks) : litteraux a forte entropie --
function _shannon(s){ var m={}, n=s.length; if(!n) return 0; for(var i=0;i<n;i++){ m[s[i]]=(m[s[i]]||0)+1; } var e=0; for(var k in m){ var p=m[k]/n; e-=p*Math.log2(p); } return e; }
var _entropyRe = /(?:key|token|secret|password|passwd|pwd|api[_-]?key|auth[_-]?token|access[_-]?token|client[_-]?secret)["']?\s*[:=]\s*["']([A-Za-z0-9+\/=_\-]{20,})["']/gi;
var _placeholder = /^(x{4,}|changeme|your[_-]|placeholder|example|sample|test|dummy|\$\{|<)/i;
for (const _f of files) {
  var _content = _f.content || "";
  var _path = _f.path || "unknown";
  if (_path.includes('.env.example') || _path.includes('.env.sample')) continue;
  _entropyRe.lastIndex = 0;
  var _mm, _seen = {};
  while ((_mm = _entropyRe.exec(_content)) !== null) {
    var _val = _mm[1];
    if (_placeholder.test(_val) || _seen[_val]) continue;
    _seen[_val] = true;
    var _ent = _shannon(_val);
    if (_ent >= 4.0) {
      var _masked = _val.substring(0,4) + '****' + _val.substring(_val.length-3);
      warnings.push({
        rule: "Secret probable (entropie " + _ent.toFixed(1) + ")",
        severity: "medium",
        owasp: "A02:2021",
        file: _path,
        description: "Chaine a forte entropie affectee a une variable sensible dans " + _path + " : " + _masked,
        impact: "Possible secret code en dur",
        fix: "Externaliser dans process.env"
      });
    }
  }
}

// Dédupliquer
const dedupKey = i => i.rule + ':' + i.file;
critical = critical.filter((v, i, a) => a.findIndex(t => dedupKey(t) === dedupKey(v)) === i);
warnings = warnings.filter((v, i, a) => a.findIndex(t => dedupKey(t) === dedupKey(v)) === i);

const secScore  = Math.max(0, 100 - (critical.length * 30) - (warnings.length * 10));
const qualScore = warnings.length > 0 ? 70 : 100;
const globalScore = Math.round((secScore * 0.8) + (qualScore * 0.2));

// WARN au lieu de NEEDSIMPROVEMENT
const status = critical.length > 0 ? "FAIL"
             : warnings.length > 0 ? "WARN"
             : "PASS";

return [{
  json: {
    agent: "Agent Secrets Scanning",
    _version: "5.1",
    task_id: input.task_id || "unknown",
    status,
    global_score: globalScore,
    approved_for_pipeline: status !== "FAIL",
    language: input.language || "javascript",
    critical_issues: critical,
    warnings,
    recommendations: critical.length > 0
      ? [
          "Révoquer immédiatement les clés exposées",
          "Utiliser des variables d'environnement (.env)",
          "Ajouter .env au .gitignore",
          "Scanner l'historique Git : git log -p | grep -E 'sk-|AKIA|ghp_'"
        ]
      : warnings.length > 0
        ? ["Externaliser les secrets dans les variables d'environnement"]
        : ["Aucun secret détecté — code sain"],
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    summary: critical.length > 0
      ? `${critical.length} secret(s) critique(s) exposé(s) — action immédiate requise`
      : warnings.length > 0
        ? `${warnings.length} secret(s) potentiel(s) détecté(s)`
        : "Aucun secret exposé dans les fichiers analysés",
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent Secrets Scanning",
    task_id: input.task_id || "unknown",
    status: "ERROR",
    error_code: input.error_code || "VALIDATION_ERROR",
    error_message: input.error_message || "Erreur de validation",
    approved_for_pipeline: false,
    timestamp: input.timestamp || new Date().toISOString()
  }
}];
